import{_ as s}from"./chunks/ArticleMetadata.1_--bNMz.js";import{_ as l,D as g,o as r,c,I as p,w as h,k as n,a as d,R as u,b as m,e as f}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const q=JSON.parse('{"title":"课程知识库、官方文档与论文","description":"","frontmatter":{"title":"课程知识库、官方文档与论文","author":"阿源","date":"2026/10/07 00:00","categories":["Agent 开发"],"tags":["课程","协议","论文","知识库"],"status":"预览版导航"},"headers":[],"relativePath":"courses/agent/01-项目与知识库导航/07-课程知识库官方文档与论文.md","filePath":"courses/agent/01-项目与知识库导航/07-课程知识库官方文档与论文.md","lastUpdated":1791349179000}'),k={name:"courses/agent/01-项目与知识库导航/07-课程知识库官方文档与论文.md"},b=n("h1",{id:"课程知识库、官方文档与论文",tabindex:"-1"},[d("课程知识库、官方文档与论文 "),n("a",{class:"header-anchor",href:"#课程知识库、官方文档与论文","aria-label":'Permalink to "课程知识库、官方文档与论文"'},"​")],-1),_=u('<p>项目 README 适合找入口，规范和论文适合确认概念边界。下面的资源用于补齐背景，不替代本课程按依赖顺序的文章。原始论文只说明研究中的方法和实验，不能自动变成生产安全保证；官方文档也可能随着版本迁移，统一记录查看日期 <strong>2026-10-07</strong>。</p><h2 id="hugging-face-agents-course" tabindex="-1">Hugging Face Agents Course <a class="header-anchor" href="#hugging-face-agents-course" aria-label="Permalink to &quot;Hugging Face Agents Course&quot;">​</a></h2><p>官方入口：<a href="https://huggingface.co/learn/agents-course/en/unit0/introduction" target="_blank" rel="noreferrer">课程 Introduction</a></p><ul><li><strong>解决的问题</strong>：以循序课程解释 Agent、工具、框架、检索和评测，并配合可运行实验。</li><li><strong>推荐学习内容</strong>：把 Unit 1 的基础概念作为入门补充，遇到框架 API 时回到本课程的协议与边界文章。</li><li><strong>前置知识</strong>：Python 基础；能够阅读英文技术文档。</li><li><strong>学习阶段</strong>：入门。</li><li><strong>阅读深度</strong>：专题查阅。</li><li><strong>推荐目录/文章</strong>：Introduction、What is an Agent?、Tools、Agentic frameworks。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：课程抽象可作为 dsh driver、tool、memory 和 multi-agent 对照的入门词典。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="anthropic-building-effective-agents" tabindex="-1">Anthropic: Building effective agents <a class="header-anchor" href="#anthropic-building-effective-agents" aria-label="Permalink to &quot;Anthropic: Building effective agents&quot;">​</a></h2><p>官方入口：<a href="https://www.anthropic.com/research/building-effective-agents" target="_blank" rel="noreferrer">原文</a></p><ul><li><strong>解决的问题</strong>：总结从简单 prompt chain 到 workflow 和 agent 的选择、边界和工程取舍。</li><li><strong>推荐学习内容</strong>：精读 augmented LLM、workflow、agent、orchestrator-workers、evaluator-optimizer，并记录何时不该增加复杂度。</li><li><strong>前置知识</strong>：Agent Loop、Workflow、Evals；第 02、09、10 章。</li><li><strong>学习阶段</strong>：进阶。</li><li><strong>阅读深度</strong>：专题查阅。</li><li><strong>推荐目录/文章</strong>：Building blocks、Workflows、Agents、When to use which pattern。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：Workflow/agent 的边界帮助定位 dsh 是否需要插件扩展，而不是把所有任务都变成多 Agent。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="openai-cookbook-agents-章节" tabindex="-1">OpenAI Cookbook Agents 章节 <a class="header-anchor" href="#openai-cookbook-agents-章节" aria-label="Permalink to &quot;OpenAI Cookbook Agents 章节&quot;">​</a></h2><p>官方入口：<a href="https://cookbook.openai.com/topic/agents" target="_blank" rel="noreferrer">Agents 主题</a></p><ul><li><strong>解决的问题</strong>：以短示例呈现 Responses、工具、handoff、tracing 和评测的组合方式。</li><li><strong>推荐学习内容</strong>：运行无需网络和密钥的结构化示例；需要模型的代码先检查环境变量、失败提示和成本。</li><li><strong>前置知识</strong>：Python 基础；第 02–04、10 章。</li><li><strong>学习阶段</strong>：进阶。</li><li><strong>阅读深度</strong>：运行实验。</li><li><strong>推荐目录/文章</strong>：agents topic、tool calling、structured outputs、evals。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：示例中的 tool call、handoff、trace 可以映射到 dsh driver/plugin/event 三层。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="datawhale-llm-cookbook" tabindex="-1">Datawhale LLM Cookbook <a class="header-anchor" href="#datawhale-llm-cookbook" aria-label="Permalink to &quot;Datawhale LLM Cookbook&quot;">​</a></h2><p>官方入口：<a href="https://github.com/datawhalechina/llm-cookbook" target="_blank" rel="noreferrer">GitHub</a></p><ul><li><strong>解决的问题</strong>：提供中文大模型应用、提示、工具调用和 RAG 的入门资料与实验入口。</li><li><strong>推荐学习内容</strong>：只把与 Agent 工程相关的章节作为中文补充；对 API/模型版本回到官方文档核对。</li><li><strong>前置知识</strong>：Python 基础；能够运行 notebook 或脚本。</li><li><strong>学习阶段</strong>：入门。</li><li><strong>阅读深度</strong>：案例参考。</li><li><strong>推荐目录/文章</strong>：大模型应用基础、函数调用、RAG、评测相关章节。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：中文资料帮助补齐 driver、tool、context 词汇，不替代 dsh 官方源码和安全说明。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="model-context-protocol-security-best-practices" tabindex="-1">Model Context Protocol Security Best Practices <a class="header-anchor" href="#model-context-protocol-security-best-practices" aria-label="Permalink to &quot;Model Context Protocol Security Best Practices&quot;">​</a></h2><p>官方入口：<a href="https://modelcontextprotocol.io/specification/2026-07-28" target="_blank" rel="noreferrer">MCP 2026-07-28 Specification 的 Security and Trust</a> · <a href="https://github.com/modelcontextprotocol/modelcontextprotocol" target="_blank" rel="noreferrer">规范仓库</a></p><ul><li><strong>解决的问题</strong>：明确 MCP token audience、confused deputy、SSRF、日志和不可信输入的安全边界。</li><li><strong>推荐学习内容</strong>：按 2026-07-28 Specification 的 Security and Trust、Consent、Data Privacy、Tool Safety 阅读；任何 tool 结果都不能直接升级为系统指令，旧安全页面只作为迁移对照。</li><li><strong>前置知识</strong>：MCP 生命周期和 OAuth 基本概念；第 06、10 章。</li><li><strong>学习阶段</strong>：生产工程。</li><li><strong>阅读深度</strong>：主线精读。</li><li><strong>推荐目录/文章</strong>：Token passthrough、Confused deputy、SSRF、User consent and data handling。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：MCP Server 的授权边界应与 dsh plugin 的 capability 和审批边界叠加，而不是互相替代。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="react-synergizing-reasoning-and-acting" tabindex="-1">ReAct: Synergizing Reasoning and Acting <a class="header-anchor" href="#react-synergizing-reasoning-and-acting" aria-label="Permalink to &quot;ReAct: Synergizing Reasoning and Acting&quot;">​</a></h2><p>原始论文：<a href="https://arxiv.org/abs/2210.03629" target="_blank" rel="noreferrer">arXiv:2210.03629</a></p><ul><li><strong>解决的问题</strong>：解释 reasoning 与 action/observation 交错的 Agent Loop 思路和可解释轨迹。</li><li><strong>推荐学习内容</strong>：精读 action-observation loop、知识获取与异常处理，不把论文轨迹直接当成生产安全方案。</li><li><strong>前置知识</strong>：Model、Tool、Observation、StopReason；第 02–04 章。</li><li><strong>学习阶段</strong>：入门。</li><li><strong>阅读深度</strong>：主线精读。</li><li><strong>推荐目录/文章</strong>：Introduction、ReAct prompting、Action spaces、Experiments。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：ReAct loop 是 dsh driver 迭代工具和事件的理论参照，dsh 还增加 plugin/session/safety 层。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="toolformer" tabindex="-1">Toolformer <a class="header-anchor" href="#toolformer" aria-label="Permalink to &quot;Toolformer&quot;">​</a></h2><p>原始论文：<a href="https://arxiv.org/abs/2302.04761" target="_blank" rel="noreferrer">arXiv:2302.04761</a></p><ul><li><strong>解决的问题</strong>：研究模型学习决定是否调用外部 API、如何传参及如何使用返回结果。</li><li><strong>推荐学习内容</strong>：重点理解 API call token、参数和结果拼接，结合第 04 章区分训练能力与运行时安全。</li><li><strong>前置知识</strong>：Message、Tool schema、ToolResult；第 03、04 章。</li><li><strong>学习阶段</strong>：进阶。</li><li><strong>阅读深度</strong>：专题查阅。</li><li><strong>推荐目录/文章</strong>：API calls、Self-supervised data、Tool use evaluation、Limitations。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：模型选工具只是 dsh driver 的一部分，插件注册、权限、审批和审计仍由 Harness 负责。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="rag-survey" tabindex="-1">RAG Survey <a class="header-anchor" href="#rag-survey" aria-label="Permalink to &quot;RAG Survey&quot;">​</a></h2><p>原始论文：<a href="https://arxiv.org/abs/2312.10997" target="_blank" rel="noreferrer">Retrieval-Augmented Generation for Large Language Models: A Survey</a></p><ul><li><strong>解决的问题</strong>：系统梳理 RAG 的数据、检索、增强、生成和评测组件及其边界。</li><li><strong>推荐学习内容</strong>：按 retrieval、augmentation、generation 和 evaluation 对照第 08 章的本地最小管线。</li><li><strong>前置知识</strong>：Embedding、检索、Citation；第 08 章。</li><li><strong>学习阶段</strong>：进阶。</li><li><strong>阅读深度</strong>：专题查阅。</li><li><strong>推荐目录/文章</strong>：RAG taxonomy、Retrieval、Augmentation、Evaluation。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：RAG 输出可作为 dsh context provider 或 tool result；权限过滤和引用仍需 Harness/应用层负责。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="a-programming-paradigm-for-spatiotemporal-composability" tabindex="-1">A Programming Paradigm for Spatiotemporal Composability <a class="header-anchor" href="#a-programming-paradigm-for-spatiotemporal-composability" aria-label="Permalink to &quot;A Programming Paradigm for Spatiotemporal Composability&quot;">​</a></h2><p>原始论文：<a href="https://arxiv.org/abs/2507.17979" target="_blank" rel="noreferrer">arXiv:2507.17979</a></p><ul><li><strong>解决的问题</strong>：解释 Cordis 的时空可组合插件范式，为理解 DeepSeek Harness 的运行时提供原始材料。</li><li><strong>推荐学习内容</strong>：在读完第 02–10 章和四个对照项目后精读 Context、service、event、scope 和生命周期。</li><li><strong>前置知识</strong>：Plugin、Hook、Event、Session；第 07、09、11 章。</li><li><strong>学习阶段</strong>：生产工程。</li><li><strong>阅读深度</strong>：主线精读。</li><li><strong>推荐目录/文章</strong>：Context and composability、Spatiotemporal model、Plugin lifecycle、Examples。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：这是理解 dsh Cordis、Everything is a Plugin 和事件系统的核心原始材料。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="读论文的最小记录模板" tabindex="-1">读论文的最小记录模板 <a class="header-anchor" href="#读论文的最小记录模板" aria-label="Permalink to &quot;读论文的最小记录模板&quot;">​</a></h2><p>读完论文或长文后，至少记录：它解决的问题、假设的输入输出、核心状态或数据结构、实验如何测量、哪些结论依赖特定模型/数据集、以及如何映射到本课程的 Agent Loop。没有这些边界时，论文中的方法名不应直接写进生产设计结论。</p>',30);function A(t,v,P,S,y,x){const a=s,i=g("ClientOnly");return r(),c("div",null,[b,p(i,null,{default:h(()=>{var o,e;return[(((o=t.$frontmatter)==null?void 0:o.aside)??!0)&&(((e=t.$frontmatter)==null?void 0:e.showArticleMetadata)??!0)?(r(),m(a,{key:0,article:t.$frontmatter},null,8,["article"])):f("",!0)]}),_:1}),_])}const T=l(k,[["render",A]]);export{q as __pageData,T as default};
